param([Parameter(Mandatory=$true)][string]$SourceRoot,[ValidateSet("Build","Ready")][string]$Expectation="Build")
$root=Split-Path -Parent $PSScriptRoot;$m=Get-Content (Join-Path $root manifest.json)-Raw|ConvertFrom-Json;$c=Get-Content (Join-Path $root ([string]$m.contracts.p14NonstandardProfessionMatrixClosure))-Raw|ConvertFrom-Json;$skill=Join-Path (Resolve-Path $SourceRoot).Path ([string]$c.sourceFiles.skillTable);$lines=Get-Content $skill
foreach($f in $c.families){$rows=@($lines|?{$n=($_-split"`t",2)[0];$n-eq$f.root-or($n.StartsWith([string]$f.root+"_")-and-not$n.StartsWith([string]$f.root+"_prereq"))}|Sort-Object);$text=($rows-join"`n")+"`n";$s=[Security.Cryptography.SHA256]::Create();try{$h=($s.ComputeHash([Text.Encoding]::UTF8.GetBytes($text))|%{$_.ToString("x2")})-join""}finally{$s.Dispose()};if($rows.Count-ne[int]$f.rows-or$h-cne[string]$f.sha256){throw "Nonstandard family failed: $($f.root)"}}
$b=$c.buildEvidence;$p=Join-Path $root ([string]$b.overlayPatch-replace"^restoration/","");if((Get-FileHash $p).Hash.ToLower()-cne[string]$b.overlayPatchSha256-or$b.globalProfessionAudit.divergences-ne0){throw "Nonstandard matrix build failed"}
if($Expectation-eq"Ready"-and$c.requiredBeforeReady.Count){throw "Runtime fixtures required before Ready"}
Write-Host "Publish 14.1 nonstandard profession matrix build closure passed."
